// Controller layer — generated by line-matcher. Do not add logic that belongs to another layer.
// Connects the workflow and domain to the page. No business logic here.
import { useMachine } from "@xstate/react";
import { orgsItemsWorkflow } from "../workflow/orgs-items.workflow.js";
import * as domain from "../domain/orgs-items.domain.js";
import OrgsItemsPage from "../page/OrgsItemsPage.jsx";

export default function OrgsItemsController() {
  const [state, send] = useMachine(orgsItemsWorkflow);
  const { items, selectedId, error } = state.context;

  return (
    <OrgsItemsPage
      status={String(state.value)}
      error={error}
      itemCount={domain.itemCount(items)}
      qtyTotal={domain.qtyTotal(items)}
      rows={domain.toOrgsItemRows(items)}
      selectedId={selectedId}
      formValues={domain.toFormValues(domain.findOrgsItem(items, selectedId))}
      onEdit={(id) => send({ type: "EDIT", id })}
      onDelete={(id) => send({ type: "DELETE", id })}
      onSave={(values) => send({ type: "SAVE", data: domain.toOrgsItemInput(values) })}
      onCancel={() => send({ type: "CANCEL" })}
    />
  );
}
